import re
import pytest


def title_of(html: str) -> str:
    """Return the text between <title> and </title> in an HTML string, or empty string."""
    match = re.search(r"<title(?:\s+[^>]*)?>(.*?)</title>", html, flags=re.IGNORECASE | re.DOTALL)
    if match is None:
        return ""
    return match.group(1)


def test_title_of_simple() -> None:
    assert title_of("<html><head><title>My Page</title></head></html>") == "My Page"


def test_title_of_missing() -> None:
    assert title_of("<html><head></head><body>No title here</body></html>") == ""


def test_title_of_empty_string() -> None:
    assert title_of("") == ""


def test_title_of_empty_tag() -> None:
    assert title_of("<title></title>") == ""


def test_title_of_case_insensitive() -> None:
    assert title_of("<TITLE>Uppercase</TITLE>") == "Uppercase"
    assert title_of("<Title>Mixed Case</title>") == "Mixed Case"


def test_title_of_with_attributes() -> None:
    assert title_of('<title lang="en" dir="ltr">With Attrs</title>') == "With Attrs"


def test_title_of_multiline() -> None:
    html = "<title>\n  Line 1\n  Line 2\n</title>"
    assert title_of(html) == "\n  Line 1\n  Line 2\n"


def test_title_of_unclosed_tag() -> None:
    assert title_of("<title>Incomplete") == ""


def test_title_of_first_title_wins() -> None:
    assert title_of("<title>First</title><title>Second</title>") == "First"

